test('frame: ball does not tunnel through brick at level 6', () => {
  const state = createState(6);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  // Ball is just above the brick, moving DOWN fast
  // Max step at lvl 6 is 35.5.
  // Ball Y = 90. After step(0.05), Y = 90 + (710 * 0.05) = 125.5.
  // Brick is from 100 to 120.
  // Ball center at 125.5, radius 7. Ball is from 118.5 to 132.5.
  // Wait, it's still colliding at 125.5 (118.5 < 120).
  // Let's make it faster or the brick thinner.
  // Actually, if ball.y - ball.r > brick.y + brick.h, it's passed.
  // Ball Y = 90. Ball bottom = 97.
  // After step: Y = 125.5. Ball top = 118.5.
  // Brick bottom = 120.
  // It still collides.

  // To tunnel, the ball must be entirely above in frame N and entirely below in frame N+1.
  // Ball top in frame N: y - 7. Ball bottom in frame N: y + 7.
  // Brick top: 100. Brick bottom: 120.
  // For the ball to be above: y + 7 < 100 => y < 93.
  // For the ball to be below: y - 7 > 120 => y > 127.
  // Distance to cover: 127 - 93 = 34.
  // Max step at lvl 6: 35.5.

  state.ball = { x: 125, y: 92, r: 7, vx: 0, vy: 710 }; // Using speed(6)

  const ctx = {
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
  };

  // Simulate one frame
  step(state, 0.05);
  frame(ctx, state);

  assert.equal(brick.alive, false, 'Brick should have been destroyed');
  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP');
});

